package com.crms.entity;import com.crms.enums.JobStatus;import jakarta.persistence.*;import java.time.Instant;@Entity public class JobPosting{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private Company company;@Column(nullable=false)private String title;@Column(length=4000)private String description;private String location,jobType;private Double minCgpa;private Integer graduationYear,maxBacklogs;@Enumerated(EnumType.STRING)private JobStatus status=JobStatus.DRAFT;private Instant createdAt=Instant.now();public Long getId(){return id;}public Company getCompany(){return company;}public void setCompany(Company v){company=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getLocation(){return location;}public void setLocation(String v){location=v;}public String getJobType(){return jobType;}public void setJobType(String v){jobType=v;}public Double getMinCgpa(){return minCgpa;}public void setMinCgpa(Double v){minCgpa=v;}public Integer getGraduationYear(){return graduationYear;}public void setGraduationYear(Integer v){graduationYear=v;}public Integer getMaxBacklogs(){return maxBacklogs;}public void setMaxBacklogs(Integer v){maxBacklogs=v;}public JobStatus getStatus(){return status;}public void setStatus(JobStatus v){status=v;}public Instant getCreatedAt(){return createdAt;}}
